-- Description: Processe the event ID 11 race results

SET search_path TO endurancetrio_hub;

-- Insert new athletes

SELECT setval('seq_athlete_id', 455, FALSE);

-- Insert new teams

SELECT setval('seq_team_id', 41, FALSE);

-- Update existing race's result_status
UPDATE race SET result_status = 'INCOMPLETE' WHERE id IN (28, 30);
UPDATE race SET result_status = 'EMPTY' WHERE id IN (29);

-- Insert individual results

SELECT setval('seq_individual_result_id', 1457, FALSE);
